 * Splits raw stdin text into lines, dropping the trailing empty entry that a
 * final newline leaves behind, then splits those lines into exactly three
 * documents separated by lines that are exactly `%%%`.
 */

export function splitLines(input) {
  if (input === '') return []
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  return lines
}

export function splitDocuments(input) {
  const lines = splitLines(input)
  const docs = [[]]
  for (const line of lines) {
    if (line === '%%%') docs.push([])
    else docs[docs.length - 1].push(line)
  }
  if (docs.length !== 3) return null
  return docs
}
"}

