{"file_path":"src/lcs.js","content":"/**
 * Computes the changes needed to turn base (A) into side (B), using a
 * longest common subsequence over whole lines with a deterministic
 * tie-break: walking both documents from the start, take a match whenever
 * the current lines are equal, otherwise advance the side whose remaining
 * subsequence is at least as long as the other's, preferring to advance the
 * base when they tie.
 *
 * Returns a list of changes `{ baseStart, baseEnd, lines }` where `lines` is
 * the run of side lines that replaces base[baseStart:baseEnd].
 */
export function diffAgainstBase(base, side) {
  const n = base.length
  const m = side.length

  // dp[i][j] = length of LCS of base[i:] and side[j:]
  const dp = new Array(n + 1)
  for (let i = 0; i <= n; i++) dp[i] = new Uint32Array(m + 1)
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      if (base[i] === side[j]) dp[i][j] = dp[i + 1][j + 1] + 1
      else dp[i][j] = Math.max(dp[i + 1][j], dp[i][j + 1])
    }
  }

  const changes = []
  let prevI = 0
  let prevJ = 0
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      if (i > prevI || j > prevJ) {
        changes.push({ baseStart: prevI, baseEnd: i, lines: side.slice(prevJ, j) })
      }
      i++
      j++
      prevI = i
      prevJ = j
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      i++
    } else {
      j++
    }
  }
  if (prevI < n || prevJ < m) {
    changes.push({ baseStart: prevI, baseEnd: n, lines: side.slice(prevJ, m) })
  }
  return changes
}
"}

