{"file_path":"src/regions.js","content":"/**
 * Groups the changes each side made against the base into merge regions,
 * following the rules in the spec: changes are gathered from both sides,
 * ordered by base start (mine before theirs at ties), and adjacent /
 * overlapping changes are absorbed into a single region. The base lines
 * before the first region and after the last one (and between regions) form
 * stable regions.
 *
 * Returns a list of region descriptors:
 *   { kind: 'stable', lines }
 *   { kind: 'resolved', from: 'mine'|'theirs'|'both', lines, mineLines, baseLines, theirsLines }
 *   { kind: 'conflict', mineLines, baseLines, theirsLines }
 */
import { diffAgainstBase } from './lcs.js'

function reconstructSide(base, regionStart, regionEnd, ownChanges) {
  const lines = []
  let pos = regionStart
  for (const change of ownChanges) {
    lines.push(...base.slice(pos, change.baseStart))
    lines.push(...change.lines)
    pos = change.baseEnd
  }
  lines.push(...base.slice(pos, regionEnd))
  return lines
}

function arraysEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false
  return true
}

export function computeRegions(mine, base, theirs) {
  const mineChanges = diffAgainstBase(base, mine).map(c => ({ ...c, side: 'mine' }))
  const theirsChanges = diffAgainstBase(base, theirs).map(c => ({ ...c, side: 'theirs' }))

  const all = [...mineChanges, ...theirsChanges].sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })

  const groups = []
  for (const change of all) {
    const last = groups[groups.length - 1]
    if (last && change.baseStart <= last.end) {
      last.end = Math.max(last.end, change.baseEnd)
      last.changes.push(change)
    } else {
      groups.push({ start: change.baseStart, end: change.baseEnd, changes: [change] })
    }
  }

  const result = []
  let prevEnd = 0
  for (const group of groups) {
    if (group.start > prevEnd) {
      result.push({ kind: 'stable', lines: base.slice(prevEnd, group.start) })
    }

    const ownMine = group.changes.filter(c => c.side === 'mine')
    const ownTheirs = group.changes.filter(c => c.side === 'theirs')
    const mineLines = reconstructSide(base, group.start, group.end, ownMine)
    const theirsLines = reconstructSide(base, group.start, group.end, ownTheirs)
    const baseLines = base.slice(group.start, group.end)

    if (arraysEqual(mineLines, theirsLines)) {
      result.push({ kind: 'resolved', from: 'both', lines: mineLines, mineLines, baseLines, theirsLines })
    } else if (arraysEqual(mineLines, baseLines)) {
      result.push({ kind: 'resolved', from: 'theirs', lines: theirsLines, mineLines, baseLines, theirsLines })
    } else if (arraysEqual(theirsLines, baseLines)) {
      result.push({ kind: 'resolved', from: 'mine', lines: mineLines, mineLines, baseLines, theirsLines })
    } else {
      result.push({ kind: 'conflict', mineLines, baseLines, theirsLines })
    }

    prevEnd = group.end
  }

  if (prevEnd < base.length) {
    result.push({ kind: 'stable', lines: base.slice(prevEnd, base.length) })
  }

  return result
}
"}

