  for (const change of all) {
    const last = groups[groups.length - 1]
    if (last && change.baseStart <= last.end) {
      last.end = Math.max(last.end, change.baseEnd)
      last.changes.push(change)
    } else {
      groups.push({ start: change.baseStart, end: change.baseEnd, changes: [change] })
    }
  }

  const result = []
  let prevEnd = 0
  for (const group of groups) {
    if (group.start > prevEnd) {
      result.push({ kind: 'stable', lines: base.slice(prevEnd, group.start) })
    }

    const ownMine = group.changes.filter(c => c.side === 'mine')
    const ownTheirs = group.changes.filter(c => c.side === 'theirs')
    const mineLines = reconstructSide(base, group.start, group.end, ownMine)
    const theirsLines = reconstructSide(base, group.start, group.end, ownTheirs)
    const baseLines = base.slice(group.start, group.end)

    if (arraysEqual(mineLines, theirsLines)) {
      result.push({ kind: 'resolved', from: 'both', lines: mineLines, mineLines, baseLines, theirsLines })
    } else if (arraysEqual(mineLines, baseLines)) {
      result.push({ kind: 'resolved', from: 'theirs', lines: theirsLines, mineLines, baseLines, theirsLines })
    } else if (arraysEqual(theirsLines, baseLines)) {
      result.push({ kind: 'resolved', from: 'mine', lines: mineLines, mineLines, baseLines, theirsLines })
    } else {
      result.push({ kind: 'conflict', mineLines, baseLines, theirsLines })
    }

    prevEnd = group.end
  }

