 * report the three-way merge of the second into the first and the third.
 */
import fs from 'node:fs'
import { splitDocuments } from './split.js'
import { computeRegions } from './regions.js'

function fail(message) {
  process.stderr.write(`${message}\n`)
  process.exit(2)
}

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  let bytesRead
  while (true) {
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.slice(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const mode = process.argv[2]
  if (mode !== 'merge' && mode !== 'merge2' && mode !== 'regions') {
    fail('error: usage: cli.js merge|merge2|regions')
  }

  const input = readStdin()
  const docs = splitDocuments(input)
  if (docs === null) {
    fail('error: expected three parts separated by %%%')
  }

  const [mine, base, theirs] = docs
  const regions = computeRegions(mine, base, theirs)

  let conflict = false
  const output = []

  if (mode === 'regions') {
    for (const region of regions) {
      if (region.kind === 'stable') {
        output.push(`stable ${region.lines.length}`)
      } else if (region.kind === 'conflict') {
        conflict = true
        output.push(`conflict mine=${region.mineLines.length} base=${region.baseLines.length} theirs=${region.theirsLines.length}`)
      } else {
        output.push(`${region.from} ${region.lines.length}`)
      }
    }
  } else {
    for (const region of regions) {
      if (region.kind === 'stable') {
        output.push(...region.lines)
      } else if (region.kind === 'resolved') {
        output.push(...region.lines)
      } else {
        conflict = true
        output.push('<<<<<<< mine')
        output.push(...region.mineLines)
        if (mode === 'merge') {
          output.push('||||||| base')
          output.push(...region.baseLines)
        }
        output.push('=======')
        output.push(...region.theirsLines)
        output.push('>>>>>>> theirs')
      }
    }
  }

  const text = output.length === 0 ? '' : `${output.join('\n')}\n`
  process.stdout.write(text)
  process.exit(conflict ? 1 : 0)
}

